<script setup lang="ts">
import {ref,watch} from 'vue'
import {useAuth} from '../stores/auth'
import {message} from '../api'
const auth=useAuth(),username=ref(auth.lastUsername||'admin'),password=ref(''),name=ref(''),confirmation=ref(''),busy=ref(false),error=ref('')
watch(()=>auth.lastUsername,value=>{if(value)username.value=value})
async function login(){busy.value=true;error.value='';try{if(auth.setupRequired&&password.value!==confirmation.value)throw Error('Пароли не совпадают');await auth.login(username.value,password.value,name.value);password.value='';confirmation.value=''}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="login-screen"><section class="login-panel"><span class="login-mark"><UIcon name="i-lucide-activity"/></span><h1>{{auth.setupRequired?'Настройка Кабинета УЗИ':auth.locked?'Сеанс заблокирован':'Вход в Кабинет УЗИ'}}</h1><p v-if="auth.setupRequired||auth.locked">{{auth.setupRequired?'Создайте первого администратора.':'Войдите снова, чтобы продолжить. Несохранённая форма остаётся на месте.'}}</p><UAlert v-if="auth.error" color="error" variant="soft" :description="auth.error"/><UButton v-if="auth.error" variant="outline" @click="auth.init">Повторить подключение</UButton><div v-if="!auth.ready" class="text-slate-600">Проверяем базу и страховочную копию…</div><form v-else-if="!auth.error" @submit.prevent="login" class="space-y-6"><UAlert v-if="error" color="error" variant="soft" :description="error"/><UFormField v-if="auth.setupRequired" label="Ваше ФИО" description="Вы получите права администратора. Врач для заключения выбирается отдельно в исследовании." required><UInput v-model="name" class="w-full" required autocomplete="name"/></UFormField><UFormField label="Логин" required><UInput v-model="username" :readonly="auth.locked" class="w-full" required autocomplete="username"/></UFormField><UFormField label="Пароль" :description="auth.setupRequired?'Не менее 10 символов. Сохраните пароль в надёжном месте.':undefined" required><UInput v-model="password" type="password" class="w-full" required :minlength="auth.setupRequired?10:undefined" :autocomplete="auth.setupRequired?'new-password':'current-password'"/></UFormField><UFormField v-if="auth.setupRequired" label="Повторите пароль" required><UInput v-model="confirmation" type="password" class="w-full" required autocomplete="new-password"/></UFormField><UButton type="submit" size="lg" block :loading="busy">{{auth.setupRequired?'Создать администратора':'Войти'}}</UButton></form></section></div></template>
